-- noctalia: Noctalia-driven Neovim colorscheme.
--
-- This file is regenerated by Noctalia on every palette change. Hand edits
-- are allowed but are overwritten as soon as the theme switches. The
-- SIGUSR1 handler at the bottom reloads it live so a running Neovim
-- session picks up new colours without a restart.
--
-- LazyVim wires this file in via lua/plugins/noctalia.lua. Users
-- without LazyVim can still load it with `:colorscheme noctalia`.

-- Palette rendered by Noctalia. Loops below index this table by role name;
-- template tags must stay literal here because they are expanded before
-- Lua ever runs.
local P = {
  surface                   = '#15121a',
  surface_container_low     = '#1d1a22',
  surface_container         = '#211e26',
  surface_container_high    = '#2c2931',
  on_surface                = '#e7e0eb',
  on_surface_variant        = '#cbc3d5',
  outline                   = '#958e9e',
  outline_variant           = '#4a4453',
  scrim                     = '#000000',
  primary                   = '#d1bcff',
  on_primary                = '#3d008f',
  primary_container         = '#582bad',
  on_primary_container      = '#c6acff',
  secondary                 = '#d0bdf6',
  on_secondary              = '#362856',
  secondary_container       = '#504171',
  on_secondary_container    = '#c2b0e7',
  tertiary                  = '#ffade3',
  on_tertiary               = '#5f004f',
  tertiary_container        = '#851970',
  on_tertiary_container     = '#ff98df',
  error                     = '#ffb4ab',
  on_error                  = '#690005',
  error_container           = '#93000a',
  on_error_container        = '#ffdad6',
  -- Terminal palette: used where a semantic hue matters (warn = yellow,
  -- added = green) and for :terminal buffers.
  yellow                    = '#d0bdf6',
  green                     = '#d1bcff',
}

---------------------------------------------------------------------------
-- Contrast guard (WCAG 2.x). Every hi() call checks its foreground against
-- the background it is actually drawn on and, if it falls short, mixes the
-- foreground towards white or black until it reaches the minimum, keeping
-- its hue. `:NoctaliaContrast` lists what was adjusted on the last load.
--
--   4.5  body text (code, menus, messages)
--   3.0  UI and accents (signs, icons, borders, line numbers, comments,
--        titles, dim/inactive labels)
--   skip deliberately faint decoration (whitespace, guides, separators)
--
-- Background-only overlays (selection, cursorline, diff, references) cannot
-- be fixed without overriding syntax colours, so they are only reported.
---------------------------------------------------------------------------
local MIN_TEXT, MIN_UI, MIN_OVERLAY = 4.5, 3.0, 3.0

local SKIP = {}
for _, g in ipairs({
  'Whitespace', 'NonText', 'EndOfBuffer', 'NeoTreeEndOfBuffer',
  'LineNrAbove', 'LineNrBelow', 'WinSeparator', 'VertSplit',
  'NeoTreeWinSeparator', 'NeoTreeVertSeparator', 'TreesitterContextSeparator',
  'BlinkCmpDocSeparator', 'LspCodeLensSeparator', 'SnacksIndent',
  'NeoTreeIndentBlank', 'NeoTreeIndentGuide', 'AerialGuide', 'TroubleIndent',
  'FlashBackdrop', 'LeapBackdrop', 'DiagnosticUnnecessary',
  'SnacksPickerScrollFloatBorder',
}) do SKIP[g] = true end

local UI_PATTERNS = {
  'sign', 'border', 'icon', '^linenr$', 'linenumber', 'cursorlinenr',
  'comment', 'title', 'flashlabel', '^leap', '^gitsigns', '^neotreegit',
  'fold', '^lazydim$', 'bufferhid', 'hidden', 'ghost', 'inlayhint',
  'codelens', 'kind', 'source', 'indicator', 'separator', 'nc$', 'footer',
  'rule', 'bufnr', 'count', 'deprecated', 'empty', 'location', 'extra',
  '^aerialline',
  '^cmpitemmenu$', '^tabline$', '^statusline$', '^specialkey$', '^conceal',
}
local OVERLAY_PATTERNS = {
  '^visual', '^cursorline$', '^quickfixline$', '^diff[act]', 'illuminated',
  '^lspreference', 'selection$', 'winselect', 'cursorline$',
}
-- Background a fg-only group is drawn on, by name prefix (first match wins).
local CONTEXT_BG = {
  { '^blinkcmpdoc', 'surface_container_high' },
  { '^blinkcmpsignature', 'surface_container_high' },
  { '^blinkcmp', 'surface_container' },
  { '^pmenu', 'surface_container' },
  { '^cmpitem', 'surface_container' },
  { '^whichkey', 'surface_container_high' },
  { '^snacksnotifier', 'surface_container' },
  { '^notify', 'surface_container' },
  { '^noice', 'surface_container' },
  { '^trouble', 'surface_container_high' },
  { '^float', 'surface_container_high' },
  { '^neotreefloat', 'surface_container_high' },
  { '^statusline', 'surface_container' },
  { '^tabline$', 'surface_container_low' },
}

local function matches(name, patterns)
  for _, p in ipairs(patterns) do
    if name:find(p) then return true end
  end
  return false
end

local function rgb(hex)
  if type(hex) ~= 'string' or not hex:match('^#%x%x%x%x%x%x$') then return nil end
  return tonumber(hex:sub(2, 3), 16), tonumber(hex:sub(4, 5), 16), tonumber(hex:sub(6, 7), 16)
end

local function luminance(hex)
  local r, g, b = rgb(hex)
  if not r then return nil end
  local function ch(c)
    c = c / 255
    return c <= 0.03928 and c / 12.92 or ((c + 0.055) / 1.055) ^ 2.4
  end
  return 0.2126 * ch(r) + 0.7152 * ch(g) + 0.0722 * ch(b)
end

local function ratio(a, b)
  local la, lb = luminance(a), luminance(b)
  if not la or not lb then return nil end
  if la < lb then la, lb = lb, la end
  return (la + 0.05) / (lb + 0.05)
end

local function mix(a, b, t)
  local r1, g1, b1 = rgb(a)
  local r2, g2, b2 = rgb(b)
  local function m(x, y) return math.floor(x + (y - x) * t + 0.5) end
  return string.format('#%02x%02x%02x', m(r1, r2), m(g1, g2), m(b1, b2))
end

-- Returns fg unchanged if it already meets `min` on bg, otherwise the
-- closest mix towards white/black (whichever contrasts more with bg).
local function ensure(fg, bg, min)
  local r = ratio(fg, bg)
  if not r or r >= min then return fg end
  local target = (ratio('#ffffff', bg) >= ratio('#000000', bg)) and '#ffffff' or '#000000'
  for i = 1, 20 do
    local c = mix(fg, target, i * 0.05)
    if ratio(c, bg) >= min then return c end
  end
  return target
end

local report = {}
_G.__noctalia_contrast = report

local function hi(group, opts)
  if not opts.link and not SKIP[group] then
    local name = group:lower()
    local fg = opts.fg ~= 'NONE' and opts.fg or nil
    local bg = opts.bg ~= 'NONE' and opts.bg or nil
    if fg then
      if not bg then
        bg = P.surface
        for _, c in ipairs(CONTEXT_BG) do
          if name:find(c[1]) then bg = P[c[2]]; break end
        end
      end
      local min = matches(name, UI_PATTERNS) and MIN_UI or MIN_TEXT
      local fixed = ensure(fg, bg, min)
      if fixed ~= fg then
        table.insert(report, { group = group, fg = fg, new = fixed, bg = bg, min = min,
          before = ratio(fg, bg), after = ratio(fixed, bg) })
        opts = vim.tbl_extend('force', opts, { fg = fixed })
      end
    elseif bg and matches(name, OVERLAY_PATTERNS) then
      local r = ratio(P.on_surface, bg)
      if r and r < MIN_OVERLAY then
        table.insert(report, { group = group, fg = P.on_surface, bg = bg, min = MIN_OVERLAY,
          before = r })
      end
    end
  end
  vim.api.nvim_set_hl(0, group, opts)
end

vim.api.nvim_create_user_command('NoctaliaContrast', function()
  local r = _G.__noctalia_contrast or {}
  if #r == 0 then
    vim.api.nvim_echo({ { 'noctalia: every checked pair meets its contrast minimum', 'MoreMsg' } }, false, {})
    return
  end
  local lines = { { string.format('noctalia: %d pair(s) below minimum\n', #r), 'Title' } }
  for _, e in ipairs(r) do
    local line
    if e.new then
      line = string.format('  %-34s %5.2f -> %5.2f  (min %.1f)  %s -> %s on %s\n',
        e.group, e.before, e.after, e.min, e.fg, e.new, e.bg)
    else
      line = string.format('  %-34s %5.2f  (min %.1f)  text %s on %s  [not fixed: overlay]\n',
        e.group, e.before, e.min, e.fg, e.bg)
    end
    table.insert(lines, { line })
  end
  vim.api.nvim_echo(lines, false, {})
end, { desc = 'Show highlight pairs adjusted by the noctalia contrast guard' })

if vim.g.colors_name then
  vim.cmd('highlight clear')
end
