  enumMember   = 'tertiary',
  variable     = 'on_surface',
  parameter    = 'on_surface_variant',
  string       = 'primary',
  number       = 'tertiary',
  boolean      = 'tertiary',
  array        = 'on_surface',
  object       = 'on_surface',
  key          = 'primary',
  null         = 'on_surface_variant',
  decorator    = 'tertiary',
  event        = 'secondary',
  operator     = 'on_surface_variant',
}
for kind, role in pairs(lsp_types) do
  hi('@lsp.type.' .. kind, { fg = P[role] })
  hi('@lsp.typemod.' .. kind .. '.readonly',       { fg = P[role], italic = true })
  hi('@lsp.typemod.' .. kind .. '.defaultLibrary', { fg = P[role], italic = true })
  hi('@lsp.typemod.' .. kind .. '.deprecated',     { fg = P[role], strikethrough = true })
end

