---------------------------------------------------------------------------
-- SIGUSR1 handler. Noctalia sends this signal after rewriting the file so
-- running Neovim sessions pick up new colours without restarting. The
-- handler reloads the colorscheme (firing ColorScheme so lualine and
-- bufferline refresh) only while noctalia is still the active scheme. A
-- previous handler is closed first to avoid stacking across reloads.
---------------------------------------------------------------------------
if _G.__noctalia_signal then
  pcall(function() _G.__noctalia_signal:stop() end)
  pcall(function() _G.__noctalia_signal:close() end)
  _G.__noctalia_signal = nil
end

local uv = vim.uv or vim.loop
local sig = uv and uv.new_signal()
if sig then
  _G.__noctalia_signal = sig
  sig:start('sigusr1', vim.schedule_wrap(function()
    if vim.g.colors_name == 'noctalia' then
      pcall(vim.cmd.colorscheme, 'noctalia')
    end
  end))
end
